 "content": "def transform(grid):
    # For each location in the 4x4 panels, output the most common
    # non-background color, with background when none is present.
    out = []
    for r in range(4):
        row = []
        for c in range(4):
            vals = [grid[r][p * 5 + c] for p in range(4)]
            vals = [v for v in vals if v != 0]
            if not vals:
                row.append(0)
            else:
                row.append(max(set(vals), key=lambda v: (vals.count(v), -vals.index(v))))
        out.append(row)
    return out
